from __future__ import annotations
from itertools import product

def table(rule: int) -> tuple[int, ...]:
    return tuple((rule >> i) & 1 for i in range(8))

def step(s: tuple[int, ...], rule: int) -> tuple[int, ...]:
    n=len(s); t=table(rule)
    return tuple(t[(s[(i-1)%n]<<2)|(s[i]<<1)|s[(i+1)%n]] for i in range(n))

def count_fixed(rule: int, n: int) -> int:
    return sum(step(s,rule)==s for s in product((0,1), repeat=n))

if __name__ == "__main__":
    for n in range(1,11):
        print(n, *(count_fixed(r,n) for r in (0,110,204)))

from __future__ import annotations

def anf(rule: int) -> tuple[int, ...]:
    a=[(rule>>i)&1 for i in range(8)]
    for bit in range(3):
        for mask in range(8):
            if mask & (1<<bit): a[mask] ^= a[mask^(1<<bit)]
    return tuple(a)

def polynomial(coeff: tuple[int,...]) -> str:
    names=("1","r","c","cr","l","lr","lc","lcr")
    terms=[names[i] for i,x in enumerate(coeff) if x]
    return " + ".join(terms) or "0"

if __name__ == "__main__":
    for rule in (0,30,90,110,204): print(rule, polynomial(anf(rule)))

from __future__ import annotations

def propagate_zero(right: list[int], start: int) -> set[int]:
    seen: set[int]=set(); i=start
    while i not in seen:
        seen.add(i); i=right[i]
    return seen

if __name__ == "__main__":
    for n in range(1,9):
        right=[(i+1)%n for i in range(n)]
        reached=propagate_zero(right,0)
        print(f"n={n}: reached {len(reached)}/{n}; singleton forced={len(reached)==n}")

